h1 {
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    color: #1a1a1a;
}

.intro-text {
    font-size: 1rem;
    color: #666;
    margin-bottom: 2rem;
    line-height: 1.6;
}

/* Form styles */
.contact-form {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

label {
    font-size: 0.95rem;
    font-weight: 600;
    color: #1a1a1a;
    display: flex;
    align-items: center;
    gap: 0.3rem;
}

.required-indicator {
    color: #e74c3c;
    font-weight: 700;
    font-size: 1.1rem;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
    padding: 0.875rem 1rem;
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    font-size: 1rem;
    font-family: inherit;
    transition: all 0.2s ease;
    background-color: #fafafa;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
    outline: none;
    border-color: #3498db;
    background-color: #fff;
    box-shadow: 0 0 0 3px rgba(52, 152, 219, 0.1);
}

input[type="text"]:disabled,
input[type="email"]:disabled,
input[type="tel"]:disabled {
    background-color: #f5f5f5;
    color: #999;
    cursor: not-allowed;
}

/* Validation states */
input[type="text"]:invalid:not(:placeholder-shown),
input[type="email"]:invalid:not(:placeholder-shown),
input[type="tel"]:invalid:not(:placeholder-shown) {
    border-color: #e74c3c;
    background-color: #fff5f5;
}

input[type="text"]:valid:not(:placeholder-shown),
input[type="email"]:valid:not(:placeholder-shown),
input[type="tel"]:valid:not(:placeholder-shown) {
    border-color: #27ae60;
    background-color: #f5fff5;
}

input[aria-invalid="true"] {
    border-color: #e74c3c;
    background-color: #fff5f5;
}

input[aria-invalid="false"] {
    border-color: #27ae60;
    background-color: #f5fff5;
}

/* Helper and error text */
.helper-text {
    font-size: 0.875rem;
    color: #666;
    font-style: italic;
    margin-top: -0.25rem;
}

.error-message {
    font-size: 0.875rem;
    color: #e74c3c;
    font-weight: 500;
    min-height: 1.25rem;
    display: flex;
    align-items: center;
}

/* Submit button */
.submit-button {
    padding: 1rem;
    background: linear-gradient(135deg, #3498db 0%, #2980b9 100%);
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 0.5rem;
    box-shadow: 0 4px 15px rgba(52, 152, 219, 0.3);
}

.submit-button:hover {
    background: linear-gradient(135deg, #2980b9 0%, #21618c 100%);
    box-shadow: 0 6px 20px rgba(52, 152, 219, 0.4);
    transform: translateY(-2px);
}

.submit-button:active {
    transform: translateY(0);
    box-shadow: 0 2px 8px rgba(52, 152, 219, 0.3);
}

.submit-button:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(52, 152, 219, 0.3), 0 4px 15px rgba(52, 152, 219, 0.3);
}

.submit-button:disabled {
    background: #bdc3c7;
    cursor: not-allowed;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
    transform: none;
}

/* Success message */
.success-message {
    padding: 1rem;
    background-color: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
    border-radius: 8px;
    font-size: 0.95rem;
    font-weight: 500;
    text-align: center;
    margin-top: 1rem;
    animation: fadeIn 0.3s ease-out;
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

/* Responsive design */
@media (max-width: 600px) {
    .content-wrapper {
        padding: 2rem;
    }

    h1 {
        font-size: 1.5rem;
    }

    body {
        padding: 1rem;
    }
}

/* Forced colors mode support */
@media (forced-colors: active) {
    input[type="text"],
    input[type="email"],
    input[type="tel"],
    .submit-button {
        border: 2px solid ButtonBorder;
        color: ButtonText;
        background-color: Canvas;
    }

    .submit-button {
        background-color: ButtonFace;
        border-color: ButtonBorder;
    }

    .submit-button:focus {
        outline: 2px solid Highlight;
        outline-offset: 2px;
    }

    .error-message {
        color: CanvasText;
    }

    .success-message {
        border: 2px solid CanvasText;
        color: CanvasText;
    }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}
