    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

label {
    font-size: 0.95rem;
    font-weight: 600;
    color: #1a1a1a;
    display: flex;
    align-items: center;
    gap: 0.3rem;
}

.required-indicator {
    color: #e74c3c;
    font-weight: 700;
    font-size: 1.1rem;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
    padding: 0.875rem 1rem;
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    font-size: 1rem;
    font-family: inherit;
    transition: all 0.2s ease;
    background-color: #fafafa;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
    outline: none;
    border-color: #3498db;
    background-color: #fff;
    box-shadow: 0 0 0 3px rgba(52, 152, 219, 0.1);
}

input[type="text"]:disabled,
input[type="email"]:disabled,
input[type="tel"]:disabled {
    background-color: #f5f5f5;
    color: #999;
    cursor: not-allowed;
}

/* Validation states */
input[type="text"]:invalid:not(:placeholder-shown),
input[type="email"]:invalid:not(:placeholder-shown),
input[type="tel"]:invalid:not(:placeholder-shown) {
    border-color: #e74c3c;
    background-color: #fff5f5;
}

input[type="text"]:valid:not(:placeholder-shown),
input[type="email"]:valid:not(:placeholder-shown),
input[type="tel"]:valid:not(:placeholder-shown) {
    border-color: #27ae60;
    background-color: #f5fff5;
}

input[aria-invalid="true"] {
    border-color: #e74c3c;
    background-color: #fff5f5;
}

input[aria-invalid="false"] {
    border-color: #27ae60;
    background-color: #f5fff5;
}

/* Helper and error text */
.helper-text {
    font-size: 0.875rem;
    color: #666;
    font-style: italic;
    margin-top: -0.25rem;
}

.error-message {
    font-size: 0.875rem;
    color: #e74c3c;
    font-weight: 500;
    min-height: 1.25rem;
    display: flex;
    align-items: center;
}

/* Submit button */
.submit-button {
    padding: 1rem;
    background: linear-gradient(135deg, #3498db 0%, #2980b9 100%);
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 0.5rem;
    box-shadow: 0 4px 15px rgba(52, 152, 219, 0.3);
}

.submit-button:hover {
    background: linear-gradient(135deg, #2980b9 0%, #21618c 100%);
    box-shadow: 0 6px 20px rgba(52, 152, 219, 0.4);
    transform: translateY(-2px);
}

.submit-button:active {
    transform: translateY(0);
    box-shadow: 0 2px 8px rgba(52, 152, 219, 0.3);
}

.submit-button:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(52, 152, 219, 0.3), 0 4px 15px rgba(52, 152, 219, 0.3);
}

